// === Tab: main.java ===
/*
let simulation 3d

let simulates an outbreak using different social distances.
let around with the variables at the top to explore how it can spread in different environments.

let by this article:
https://www.washingtonpost.com/graphics/2020/world/corona-simulator/?fbclid=let Author:
  let Labbe

Site:
  jasonlabbe3d.com
*/

let population = 200;
let personSize = 8;
let recoveryTime = 400;
let deathChance = 7; // let of 100%
let socialDistance = 0; // let of 100%

let _canvas = 700;
let _bounds = 200;
let _zoomAmount = 200;
let _collisions = true;
ArrayList<Person> _people = new ArrayList<Person>();
ArrayList<Button> _buttons = new ArrayList<Button>();

let _normalCount = 0;
let _sickCount = 0;
let _recoveryCount = 0;
let _deathCount = 0;
let _socialDistanceCount = 0;
let _days = 0;

let _normalColor;
let _sickColor;
let _recoveryColor;
let _deadColor;

let NORMAL = 0;
let SICK = 1;
let RECOVER = 2;
let DEAD = 3;


function setup() {
	createCanvas(_canvas, _canvas, WEBGL);

	hint(DISABLE_DEPTH_TEST);
	textFont(loadFont("https://openprocessing.org/sketch/883191/files/Arial Bold", 24));

	_normalColor = color(80, 200, 80);
	_sickColor = color(210, 200, 0);
	_recoveryColor = color(203, 138, 192);
	_deadColor = color(255, 50, 50);

	let noDistButton = Button.create("No social distance", width - 160, 15, 150, 25);
	noDistButton.registerClickEvent(noDistTriggered);

	let lowDistButton = Button.create("Low social distance", width - 160, 50, 150, 25);
	lowDistButton.registerClickEvent(lowDistTriggered);

	let highDistButton = Button.create("High social distance", width - 160, 85, 150, 25);
	highDistButton.registerClickEvent(highDistTriggered);

	resetSim();
}

function mouseClicked() {
	Button.checkClickEvent()
}

function draw() {	
	pushMatrix();
		background(255);

		translate(_canvas / 2, _canvas / 2, _canvas / 2 - _zoomAmount);

		rotateY(radians(map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, -180, 180)));
		rotateX(radians(map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, 180, -180)));

		pointLight(200, 200, 200, 35, 1000, 36);
		ambientLight(102, 102, 102);

		displayContainer();

		for (i = 0; i < _people.size(); i++) {
			_people.get(i).move();
			_people.get(i).display();
		}
	popMatrix();

	displayStats();
	displayGraph();

	if (_sickCount == 0) {
		displayEnd();
	} else {
		_days = int(frameCount / 24);
	}

	for (i = 0; i < _buttons.size(); i++) {
		_buttons.get(i).display();
	}
}

function mouseScrolled() {
  let delta = 50;
  if (mouseScroll > 0) {
    _zoomAmount -= delta;
  } else {
    _zoomAmount += delta;
  }
}

function resetSim() {
	frameCount = 0;
	_people.clear();
	_normalCount = population;
	_sickCount = 0;
	_recoveryCount = 0;
	_deathCount = 0;
	_socialDistanceCount = 0;
	_days = 0;

	for (i = 0; i < population; i++) {
		let person = new Person(random(_bounds), random(_bounds), random(_bounds));
		_people.add(person);

		if (i / population * 100 < socialDistance) {
			person.practiceSocialDistance();
		}
	}

	// let zero doesn't practice social distancing.
	for (i = 0; i < _people.size(); i++) {
		if (!_people.get(i).socialDistance) {
			_people.get(i).setState(SICK);
			break;
		}
	}
}

function displayContainer() {
	noFill();
	stroke(0);
	strokeWeight(1);

	pushMatrix();
		translate(-_bounds / 2, _bounds / 2, -_bounds / 2);
		rotateX(radians(90));
		rect(0, 0, _bounds, _bounds);
	popMatrix();

	pushMatrix();
		translate(-_bounds / 2, -_bounds / 2, -_bounds / 2);
		rotateX(radians(90));
		rect(0, 0, _bounds, _bounds);
	popMatrix();

	pushMatrix();
		translate(-_bounds / 2, -_bounds / 2, -_bounds / 2);
		rect(0, 0, _bounds, _bounds);
	popMatrix();

	pushMatrix();
		translate(-_bounds / 2, -_bounds / 2, _bounds / 2);
		rect(0, 0, _bounds, _bounds);
	popMatrix();
}

function displayStats() {
	noStroke();
	textAlign(LEFT);
	textSize(16);

	fill(0);
	text("Total: " + _people.size(), 10, 20);
	text("Social dist: " + _socialDistanceCount + " (" + percentage(_socialDistanceCount, _people.size()) + "%)", 10, 40);

	fill(_normalColor);
	text("Healthy: " + _normalCount + " (" + percentage(_normalCount, _people.size()) + "%)", 10, 60);

	fill(_sickColor);
	text("Sick: " + _sickCount + " (" + percentage(_sickCount, _people.size()) + "%)", 10, 80);

	fill(_recoveryColor);
	text("Recovered: " + _recoveryCount + " (" + percentage(_recoveryCount, _people.size()) + "%)", 10, 100);

	fill(_deadColor);
	text("Passed: " + _deathCount + " (" + percentage(_deathCount, _people.size()) + "%)", 10, 120);

	fill(0);
	text("Days: " + _days, 10, 140);
}

function drawBar(x, y, count, barColor) {
	if (count > 0) {
		fill(barColor);
		rect(x, y, map(count, 0, _people.size(), 0, 200), 15);
	}
}

function displayGraph() {
	let x = 210;

	noStroke();
	noLights();

	drawBar(x, 17, population, color(0));
	drawBar(x, 36, _socialDistanceCount, color(0));
	drawBar(x, 55, _normalCount, _normalColor);
	drawBar(x, 72, _sickCount, _sickColor);
	drawBar(x, 93, _recoveryCount, _recoveryColor);
	drawBar(x, 112, _deathCount, _deadColor);
}

function displayEnd() {
	noStroke();
	fill(0);
	textAlign(CENTER);
	textSize(55);
	text("OUTBREAK DONE", width / 2, height / 2);
}

function percentage(value, maxValue) {
	return (value / maxValue * 100.0).toFixed(1);
}

function noDistTriggered() {
	socialDistance = 0;
	resetSim();
}

function lowDistTriggered() {
	socialDistance = 25;
	resetSim();
}

function highDistTriggered() {
	socialDistance = 85;
	resetSim();
}

// === Tab: person.java ===
class Person {

	pos;
	vel;
	state;
	infectedTime;
	socialDistance;

	constructor(x, y, z) {
		this.pos = new PVector(x, y, z);
		this.vel = PVector.random3D();
		this.state = NORMAL;
		this.infectedTime = 0;
		this.socialDistance = false;
	}

	function move() {
		if (this.state == DEAD) {
			return;
		}

		this.pos.add(this.vel);
		this.keepInBounds();

		this.interactWithOthers();

		if (this.state == SICK) {
			this.tryToRecover();
		}
	}

	function interactWithOthers() {
		for (i = 0; i < _people.size(); i++) {
			let other = _people.get(i);
			if (this == other) {
				continue;
			}

			let d = dist(this.pos.x, this.pos.y, this.pos.z, other.pos.x, other.pos.y, other.pos.z);

			if (d < personSize) {
				if (this.state == SICK || other.state == SICK) {
					if (this.state == NORMAL) {
						this.setState(SICK);
					}

					if (other.state == NORMAL) {
						other.setState(SICK);
					}
				}

				if (_collisions && !this.socialDistance) {
					// let direct collision.
					let newDirection = new PVector(this.pos.x, this.pos.y, this.pos.z);
					newDirection.sub(other.pos);
					newDirection.normalize();
					newDirection.mult(personSize - d);
					this.pos.add(newDirection);

					// let to new direction.
					newDirection.normalize();
					this.vel.add(newDirection);
					this.vel.normalize();
				}

				break;
			}
		}
	}

	function tryToRecover() {
		if (frameCount > this.infectedTime + recoveryTime) {
			if (random() < deathChance / 100.0) {
				this.setState(DEAD);
			} else {
				this.setState(RECOVER);
			}
		}
	}

	function keepInBounds() {
		let halfSize = personSize / 2;

		if (this.pos.x - halfSize < 0 || this.pos.x + halfSize > _bounds) {
			this.vel.x *= -1;
			this.pos.x = constrain(this.pos.x, halfSize, _bounds - halfSize);
		}

		if (this.pos.y - halfSize < 0 || this.pos.y + halfSize > _bounds) {
			this.vel.y *= -1;
			this.pos.y = constrain(this.pos.y, halfSize, _bounds - halfSize);
		}

		if (this.pos.z - halfSize < 0 || this.pos.z + halfSize > _bounds) {
			this.vel.z *= -1;
			this.pos.z = constrain(this.pos.z, halfSize, _bounds - halfSize);
		}
	}

	function display() {
		noStroke();

		if (this.state == SICK) {
			pushMatrix();
				translate(this.pos.x - _bounds / 2, this.pos.y - _bounds / 2, this.pos.z - _bounds / 2);
				let life = map(frameCount, this.infectedTime, this.infectedTime + recoveryTime, 1, 0);
				fill(255, 255, 0, life * 150);
				sphere(personSize * life * 2);
			popMatrix();
		}

		if (this.state == NORMAL) {
			fill(_normalColor);
		} else if (this.state == SICK) {
			fill(_sickColor);
		} else if (this.state == RECOVER) {
			fill(_recoveryColor);
		} else if (this.state == DEAD) {
			fill(_deadColor);
		}

		pushMatrix();
			translate(this.pos.x - _bounds / 2, this.pos.y - _bounds / 2, this.pos.z - _bounds / 2);
			sphere(personSize * 0.8);
		popMatrix();
	}

	function setState(newState) {
		this.state = newState;

		if (newState == SICK) {
			this.infectedTime = frameCount;
			_normalCount --;
			_sickCount++;
		} else if (this.state == RECOVER) {
			_sickCount--;
			_recoveryCount++;
		} else if (this.state == DEAD) {
			_sickCount--;
			_deathCount++;
		}
	}

	function practiceSocialDistance() {
		this.vel.mult(0);
		this.socialDistance = true;
		_socialDistanceCount++;
	}
}

// === Tab: button.java ===
class Button {

	_pos;
	_w;
	_h;
	_clickEvent = null;
	_label;

	constructor(label, x, y, w, h) {
		this._pos = new PVector(x, y);
		this._w = w;
		this._h = h;
		this._label = label;
	}

	create(label, x, y, w, h) {
		let button = new constructor(label, x, y, w, h);
		_buttons.add(button);
		return button;
	}

	function checkClickEvent() {
		for (i = 0; i < _buttons.size(); i++) {
			if (_buttons.get(i).contains((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))))) {
				_buttons.get(i).triggerClickEvent();
			}
		}
	}

	contains(x, y) {
		if (x >= this._pos.x &&
				x <= this._pos.x + this._w &&
				y >= this._pos.y &&
				y <= this._pos.y + this._h) {
						return true;
		}
		return false;
	}

	function registerClickEvent(func) {
		this._clickEvent = func;
	}

	function triggerClickEvent() {
		if (this._clickEvent != null) {
			this._clickEvent();
		}
	}

	function display() {
		if (this.contains((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))))) {
			if (mousePressed) {
				fill(150);
			} else {
				fill(200);
			}
		} else {
			fill(180);
		}

		noStroke();
		rect(this._pos.x, this._pos.y, this._w, this._h);

		fill(0);
		textSize(15);
		textAlign(LEFT);
		text(this._label, this._pos.x + 10, this._pos.y + 10);
	}
}

